const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || {};
const clean = v => (v === undefined || v === null) ? '' : String(v).trim();
const ev = { event_type: 'ignored', received_at: new Date().toISOString(), email: '', phone: '', first_name: '', last_name: '', message: '', checkout_id: '', recovery_url: '', cart_items: '', cart_total: 0, order_id: '', order_total: 0, prior_order_count: 0, run_id: headers['x-demo-run-id'] || body.run_id || '' };
if (item.source === 'shopify') {
  const topic = headers['x-shopify-topic'];
  const customer = body.customer || {};
  const ship = body.shipping_address || {};
  const bill = body.billing_address || {};
  ev.email = clean(body.email || customer.email).toLowerCase();
  // What the shopper typed in this checkout wins over Shopify's saved customer record, which keeps the name of an earlier order
  // with the same email (real test, 23 Nov 2026: Shopify showed 'Thank you Anna', the customer record said 'Piero Pelu').
  ev.phone = clean(body.phone || bill.phone || ship.phone || customer.phone);
  const named = [bill, ship, customer].find(x => clean(x.first_name)) || {};
  ev.first_name = clean(named.first_name);
  ev.last_name = clean(named.last_name);
  // Shopify sends checkouts/create when the checkout page opens, before any email; the email first arrives in a checkouts/update.
  // An update counts as a cart event unless the checkout is already completed (paid); the cart handler starts once per checkout.
  if (topic === 'checkouts/create' || (topic === 'checkouts/update' && !body.completed_at)) {
    ev.event_type = 'checkout_created';
    ev.checkout_id = clean(body.token || body.id);
    ev.recovery_url = clean(body.abandoned_checkout_url);
    ev.cart_items = (body.line_items || []).map(li => li.title + ' x' + li.quantity).join(', ');
    ev.cart_total = Number(body.total_price || 0);
  } else if (topic === 'orders/paid') {
    ev.event_type = 'order_paid';
    ev.order_id = clean(body.id);
    ev.order_total = Number(body.total_price || 0);
    ev.checkout_id = clean(body.checkout_token || body.checkout_id);
    ev.prior_order_count = Math.max(0, Number(customer.orders_count || 1) - 1);
  }
} else if (item.source === 'form') {
  const parts = clean(body.name).split(' ');
  ev.event_type = body.event_type === 'contact_form' ? 'contact_form' : 'ignored';
  ev.email = clean(body.email).toLowerCase();
  ev.phone = clean(body.phone);
  ev.first_name = clean(body.first_name || parts[0]);
  ev.last_name = clean(body.last_name || parts.slice(1).join(' '));
  ev.message = clean(body.message);
} else {
  ev.event_type = 'winback_run';
}
// The GoHighLevel node refuses a phone with spaces or dashes ('+48 500 000 001' fails, '+48500000001' works; real test 23 Nov 2026).
// Keep only digits and a leading +; a leading 00 becomes +.
ev.phone = ev.phone.replace(/^00/, '+').replace(/(?!^\+)\D/g, '');
const s = $('Store Settings').first().json;
const settings = {};
for (const k of ['cart_wait_seconds', 'winback_first_days', 'winback_sms_gap_days', 'winback_cooldown_days', 'winback_enabled', 'email_mode', 'store_url', 'offer_text', 'response_time', 'from_email', 'adapter_config', 'email_sender_id']) settings[k] = s[k];
// Each n8n picks its own mode. On the test copy (its address contains test_instance_host; written without 'n8n.' so the sync's address swap leaves it alone) every event uses the mock adapter and Mailpit,
// so a local copy never touches real customers and a sync never switches the server to test mode. Any other n8n uses the settings above.
settings.test_instance = !!s.test_instance_host && String($execution.resumeUrl || '').includes(s.test_instance_host);
if (settings.test_instance) {
  settings.adapter_config = { ...(s.adapter_config || {}), mode: 'mock' };
  settings.email_mode = 'mailpit';
}
// One switch: adapter_config.mode 'live' uses the real GoHighLevel adapter, anything else the mock.
settings.ghl_adapter_id = (settings.adapter_config || {}).mode === 'live' ? s.ghl_adapter_live_id : s.ghl_adapter_mock_id;
return [{ json: { ...settings, ...ev } }];
